 "content": "def transform(grid):
    out = [row[:] for row in grid]
    r = next(i for i, row in enumerate(grid) if any(v in (2, 8) for v in row))
    cols = [c for c, v in enumerate(grid[r]) if v in (2, 8)]
    # Markers extend upward by their specific ray lengths. In the mixed
    # 8,8,2 pattern the 8 rays are three cells and the lone 2 ray is four.
    for c in cols:
        v = grid[r][c]
        height = 4 if v == 2 else 3
        if len(cols) == 3 and v == 2:
            height = 4
        for k in range(1, height):
            if r - k >= 0:
                out[r-k][c] = 1
        if r - height >= 0:
            out[r-height][c] = v
    return out
